from copy import deepcopy
from math import isfinite
from numbers import Real


class StrokeBuffer:
    COLORS = {"black", "amber", "cyan", "violet"}

    def __init__(self):
        self._completed = []
        self._active = None

    def start(self, color, stride=1):
        if self._active is not None:
            raise RuntimeError("a stroke is already active")
        if not isinstance(color, str):
            raise TypeError("color must be a string")
        if color not in self.COLORS:
            raise ValueError("unsupported color")
        if isinstance(stride, bool) or not isinstance(stride, int):
            raise TypeError("stride must be an integer")
        if not 1 <= stride <= 3:
            raise ValueError("stride must be between 1 and 3")
        self._active = {"color": color, "stride": stride, "seen": 0, "points": []}

    def add(self, x, y):
        if self._active is None:
            raise RuntimeError("no stroke is active")
        if isinstance(x, bool) or isinstance(y, bool) or not isinstance(x, Real) or not isinstance(y, Real):
            raise TypeError("coordinates must be real numbers")
        if not isfinite(x) or not isfinite(y):
            raise ValueError("coordinates must be finite")
        index = self._active["seen"]
        if (index + 1) % self._active["stride"] == 0:
            self._active["points"].append((x, y))
        self._active["seen"] += 1

    def stop(self, clear=False):
        if self._active is None:
            raise RuntimeError("no stroke is active")
        if not isinstance(clear, bool):
            raise TypeError("clear must be a boolean")
        stroke = {
            "color": self._active["color"],
            "points": list(self._active["points"]),
        }
        self._completed.append(stroke)
        self._active = None
        result = deepcopy(stroke)
        if clear:
            self._completed.clear()
        return result

    def clear(self):
        self._completed.clear()

    def snapshot(self):
        return deepcopy(self._completed)

